		newSize *= dim
	}

	if newSize != len(t.Data) {
		return nil, fmt.Errorf("cannot reshape tensor from %v to %v: total number of elements mismatch (%d vs %d)", t.Shape, newShape, len(t.Data), newSize)
	}

	resultTensor := &Tensor{
