		Device:		t.Device,
		gpuData:	t.gpuData,
		gpuSync:	t.gpuSync,
		needsSyncHost:	t.needsSyncHost,
	}
	if resultTensor.RequiresGrad {
		resultTensor.Creator = &ReshapeOperation{t, t.Shape}
	}
	return resultTensor, nil
}
