		var r rectr
		if err := json.Unmarshal([]byte(line), &r); err != nil {
			continue
		}
		total++
		if len(r.Edits) > 0 && string(r.Edits) != "null" {
			parsed++
		}
		if r.Success {
			success++
		}
	}
	fmt.Printf("Total requests: %d\nParsed (edits non-empty): %d\nSuccessful executions: %d\n", total, parsed, success)
}
