		if ok && gd.Tok == token.IMPORT {
			pos := anchor
			if n := len(gd.Specs); n > 0 {
				pos = gd.Specs[n-1].End()
			}
			gd.Specs = append(gd.Specs, mkSpec(pos))
			return
		}
	}
	f.Decls = append([]ast.Decl{&ast.GenDecl{
		Tok:	token.IMPORT,
		TokPos:	anchor,
		Specs:	[]ast.Spec{mkSpec(anchor)},
	}}, f.Decls...)
}
