	if t := runnableMakeTarget("run make " + target); t != "" {
		out := "run make " + t
		fmt.Printf("gollemer [%s]> %s\n", MakefileDomain, out)
		conv.AddReply(out, MakefileDomain, false)
		offerRunMakeCommand(r, projectRoot, t)
		return true
	}

	if isMakeTarget(target) {
