		conv.AddReply(out, MakefileDomain, false)
		return true
	}
	out := fmt.Sprintf("I don't know a make target called %q. Say \"list the commands\" to see them all.", target)
	fmt.Printf("gollemer [%s]> %s\n", MakefileDomain, out)
	conv.AddReply(out, MakefileDomain, false)
	return true
}
