	for _, fn := range pkg.Funcs {
		if !fn.IsTest {
			fns = append(fns, fn)
		}
	}
	sort.Slice(fns, func(i, j int) bool { return fns[i].Score > fns[j].Score })
	if len(fns) > 0 {
		b.WriteString("  Key functions:\n")
		for i, fn := range fns {
			if i >= 5 {
				break
			}
			fmt.Fprintf(&b, "    %s — %s\n", fn.Display(), fn.Summary())
		}
	}
	return b.String()
}
