// readEscape parses an escape sequence. A lone ESC (nothing follows
// within 80ms) is ignored.
func readEscape(f *os.File) (keyCode, rune) {
	f.SetReadDeadline(time.Now().Add(80 * time.Millisecond))
	var b [1]byte
	n, err := f.Read(b[:])
	f.SetReadDeadline(time.Time{})
	if err != nil || n == 0 {
		return keyIgnore, 0
	}
	switch b[0] {
	case '[':
		return readCSI(f)
	case 'O':
		var c [1]byte
		if _, err := f.Read(c[:]); err != nil {
			return keyIgnore, 0
		}
		switch c[0] {
		case 'A':
			return keyUp, 0
		case 'B':
			return keyDown, 0
		case 'C':
			return keyRight, 0
		case 'D':
			return keyLeft, 0
		case 'H':
			return keyHome, 0
		case 'F':
			return keyEnd, 0
		}
	}
	return keyIgnore, 0
}
