		res := d.Type.Results.List
		if len(res) == 1 && len(res[0].Names) == 0 {
			b.WriteString(" " + typeString(res[0].Type))
		} else {
			b.WriteString(" (" + fieldListString(res) + ")")
		}
	}
	return b.String()
}
