		if res := sig.Results(); res != nil {
			for i := 0; i < res.Len(); i++ {
				rt := res.At(i).Type()
				if isErrorType(rt) {
					continue
				}
				if hasCloseMethod(rt) {
					return i
				}
			}
		}
	}

	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return -1
	}
	name := sel.Sel.Name
	switch {
	case name == "Get" || name == "Post" || name == "Head":
		if a.isPkg(sel, "net/http") || identName(sel.X) == "http" {
			return 0
		}
	case resourceMethods[name]:
		return 0
	}
	return -1
}
